#!/usr/bin/env python3
"""IPv6 sparse-node codec: joint cut placement (compile) and image lookup.

Reads one JSON request per line from stdin, writes exactly one JSON response
per line to stdout.  Requests are independent.

The module implements:

  * strict request parsing (duplicate keys, non-finite numbers, unknown keys,
    wrong types and out-of-range values are rejected),
  * canonical pure-hexadecimal IPv6 rendering,
  * the deterministic sparse-node layout described by the task contract,
  * exact rational minimisation of the peak stage utilisation over all legal
    cut vectors,
  * image validation and longest-prefix-match lookup.
"""

import json
import os
import struct
import subprocess
import sys
import tempfile
from itertools import accumulate, repeat
from math import gcd
from operator import add, and_, mul

HERE = os.path.dirname(os.path.realpath(__file__))

MAX_FIB = 2048
MAX_ADDRS = 20000
MAX_STAGES = 16
MIN_STAGES = 4
MAX_CAP = 10 ** 9
MAX_STRIDE = 32
MAX_HOP = 65535


class Invalid(Exception):
    """Raised for any malformed request, image or address."""


# --------------------------------------------------------------------------
# small helpers
# --------------------------------------------------------------------------

def is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def align8(x):
    return (x + 7) & ~7


def align64(x):
    return (x + 63) & ~63


HEXVAL = {}
for _i, _c in enumerate('0123456789abcdef'):
    HEXVAL[_c] = _i
    HEXVAL[_c.upper()] = _i


def trunc(addr, length):
    """First `length` bits of `addr`, remaining bits zero."""
    if length >= 128:
        return addr
    return (addr >> (128 - length)) << (128 - length)


# --------------------------------------------------------------------------
# IPv6 parsing / rendering
# --------------------------------------------------------------------------

def parse_ipv6(text):
    """Parse a pure hexadecimal IPv6 address, returning the 128 bit integer."""
    if not isinstance(text, str) or not text:
        raise Invalid()
    if '/' in text or '.' in text or '%' in text:
        raise Invalid()
    if text.count('::') > 1:
        raise Invalid()
    if '::' in text:
        left, right = text.split('::')
        if left:
            lgroups = left.split(':')
            if lgroups[0] == '' or lgroups[-1] == '':
                raise Invalid()
        else:
            lgroups = []
        if right:
            rgroups = right.split(':')
            if rgroups[0] == '' or rgroups[-1] == '':
                raise Invalid()
        else:
            rgroups = []
        total = len(lgroups) + len(rgroups)
        if total > 7:
            raise Invalid()
        groups = lgroups + ['0'] * (8 - total) + rgroups
    else:
        groups = text.split(':')
        if len(groups) != 8:
            raise Invalid()
    value = 0
    for grp in groups:
        if not (1 <= len(grp) <= 4):
            raise Invalid()
        v = 0
        for ch in grp:
            d = HEXVAL.get(ch)
            if d is None:
                raise Invalid()
            v = (v << 4) | d
        value = (value << 16) | v
    return value


def parse_prefix(text):
    """Parse `address/length`, requiring zero host bits.  Returns (addr, len)."""
    if not isinstance(text, str):
        raise Invalid()
    if text.count('/') != 1:
        raise Invalid()
    aspec, lspec = text.split('/')
    if not lspec or len(lspec) > 3:
        raise Invalid()
    for ch in lspec:
        if ch < '0' or ch > '9':
            raise Invalid()
    if len(lspec) > 1 and lspec[0] == '0':
        raise Invalid()
    length = int(lspec)
    if length > 128:
        raise Invalid()
    addr = parse_ipv6(aspec)
    if trunc(addr, length) != addr:
        raise Invalid()
    return addr, length


def canonical_addr(addr):
    """RFC 5952 style canonical pure hexadecimal rendering of an address."""
    groups = [(addr >> (16 * (7 - i))) & 0xffff for i in range(8)]
    best_at = -1
    best_len = 0
    i = 0
    while i < 8:
        if groups[i] == 0:
            j = i
            while j < 8 and groups[j] == 0:
                j += 1
            run = j - i
            if run >= 2 and run > best_len:
                best_at = i
                best_len = run
            i = j
        else:
            i += 1
    if best_at < 0:
        return ':'.join('%x' % g for g in groups)
    left = ':'.join('%x' % g for g in groups[:best_at])
    right = ':'.join('%x' % g for g in groups[best_at + best_len:])
    return left + '::' + right


def canonical_prefix(addr, length):
    return canonical_addr(addr) + '/' + str(length)


# --------------------------------------------------------------------------
# trie over the FIB
# --------------------------------------------------------------------------

class Trie(object):
    """Binary trie of the FIB prefixes.

    Nodes are stored per depth in canonical (unsigned address) order; the
    children of a node occupy a contiguous range in the next depth's list.
    """

    def __init__(self, entries):
        child = {}
        parent = [-1]
        pathbit = [0]
        marked = [0]
        depth = [0]
        maxdepth = 0
        for addr, length in entries:
            cur = 0
            for d in range(length):
                bit = (addr >> (127 - d)) & 1
                key = (cur << 1) | bit
                nxt = child.get(key)
                if nxt is None:
                    nxt = len(parent)
                    child[key] = nxt
                    parent.append(cur)
                    pathbit.append(bit)
                    marked.append(0)
                    depth.append(d + 1)
                cur = nxt
            marked[cur] = 1
            if length > maxdepth:
                maxdepth = length
        self.marked = marked
        self.depth = depth
        # group nodes per depth
        buckets = [[] for _ in range(maxdepth + 1)]
        for idx in range(len(parent)):
            buckets[depth[idx]].append(idx)
        # order every level by address: sort children by (parent position, bit)
        levels = []
        positions = []
        for d in range(maxdepth + 1):
            if d == 0:
                levels.append([0])
                positions.append({0: 0})
                continue
            prev_pos = positions[d - 1]
            rows = sorted((prev_pos[parent[i]], pathbit[i], i) for i in buckets[d])
            levels.append([r[2] for r in rows])
            positions.append({r[2]: j for j, r in enumerate(rows)})
        self.levels = levels
        self.marked_levels = [[marked[i] for i in lvl] for lvl in levels]
        # child ranges: for each node of level d the [start, stop) range of its
        # children inside level d+1
        self.child_lo = []
        self.child_hi = []
        for d in range(maxdepth):
            pp = []
            for i in levels[d + 1]:
                pp.append(positions[d][parent[i]])
            lo = []
            hi = []
            j = 0
            m1 = len(pp)
            for p in range(len(levels[d])):
                start = j
                while j < m1 and pp[j] == p:
                    j += 1
                lo.append(start)
                hi.append(j)
            self.child_lo.append(lo)
            self.child_hi.append(hi)


def compute_f_py(entries, max_stride):
    """Exact stage usage table F[b][e] for every legal cut pair."""
    trie = Trie(entries)
    levels = trie.levels
    marked_levels = trie.marked_levels
    maxdepth = len(levels) - 1
    table = [[0] * 129 for _ in range(129)]
    cnt_next = None
    live_next = None
    m_next = None
    for d in range(maxdepth, -1, -1):
        m = len(levels[d])
        kmax = max_stride if max_stride <= 128 - d else 128 - d
        cnt = [[0] * m for _ in range(kmax + 1)]
        live = [[0] * m for _ in range(kmax + 1)]
        totals = [0] * m
        cnt[0] = list(marked_levels[d])
        if d < maxdepth:
            lo = trie.child_lo[d]
            hi = trie.child_hi[d]
            base = list(map(add, cnt_next[0], m_next))
            pre = [0] + list(accumulate(base))
            totals = [pre[hi[j]] - pre[lo[j]] for j in range(m)]
            for k in range(1, kmax + 1):
                pre = [0] + list(accumulate(cnt_next[k - 1]))
                cnt[k] = [pre[hi[j]] - pre[lo[j]] for j in range(m)]
                pre = [0] + list(accumulate(live_next[k - 1]))
                live[k] = [pre[hi[j]] - pre[lo[j]] for j in range(m)]
        live[0] = [1 if t > 0 else 0 for t in totals]
        if d == 0:
            for t in range(1, kmax + 1):
                acc = 32 if marked_levels[0][0] else 0
                for k in range(1, t + 1):
                    acc += cnt[k][0] * (32 + align8(k))
                cost = 128 + acc + live[t][0] * (32 + align8(t))
                table[0][t] = align64(cost)
        else:
            mask = [(-1 if v else 0) for v in live[0]]
            running = [0] * m
            for t in range(1, kmax + 1):
                w = 32 + align8(t)
                running = list(map(add, running, map(mul, cnt[t], repeat(w))))
                cost = list(map(add, running, map(mul, live[t], repeat(w))))
                cost = list(map(add, cost, repeat(128)))
                cost = list(map(and_, map(add, cost, repeat(63)), repeat(-64)))
                cost = list(map(and_, cost, mask))
                table[d][d + t] = sum(cost)
        cnt_next = cnt
        live_next = live
        m_next = totals
    return table


# --------------------------------------------------------------------------
# native helper (optional, used for speed)
# --------------------------------------------------------------------------

_HELPER = None
_HELPER_TRIED = False
_HELPER_MAGIC = 0x31424654


def _build_helper():
    src = os.path.join(HERE, 'ftab.c')
    if not os.path.isfile(src):
        return None
    try:
        with open(src, 'rb') as fh:
            blob = fh.read()
    except OSError:
        return None
    try:
        import hashlib
        tag = hashlib.sha256(blob).hexdigest()[:16]
    except Exception:
        tag = 'default'
    base = os.path.join(tempfile.gettempdir(), 'ipv6-pipeline-cache')
    target = os.path.join(base, 'ftab-' + tag)
    if os.path.isfile(target) and os.access(target, os.X_OK):
        return target
    for outdir in (base, HERE, tempfile.mkdtemp(prefix='ipv6-pipeline-')):
        try:
            os.makedirs(outdir, exist_ok=True)
            tmp = os.path.join(outdir, '.ftab-%d-%d' % (os.getpid(), id(blob)))
            cmd = ['cc', '-O2', '-std=c99', '-o', tmp, src]
            proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            if proc.returncode != 0 or not os.path.isfile(tmp):
                continue
            os.chmod(tmp, 0o755)
            try:
                os.replace(tmp, target)
            except OSError:
                pass
            return tmp
        except OSError:
            continue
    return None


def helper_path():
    global _HELPER, _HELPER_TRIED
    if not _HELPER_TRIED:
        _HELPER_TRIED = True
        if not os.environ.get('IPV6_PIPELINE_NO_NATIVE'):
            try:
                _HELPER = _build_helper()
            except Exception:
                _HELPER = None
    return _HELPER


def compute_f(entries, max_stride):
    """Stage usage table, using the native helper when it is available."""
    helper = helper_path()
    if helper is not None:
        try:
            payload = bytearray(struct.pack('<III', _HELPER_MAGIC, max_stride, len(entries)))
            for addr, length in entries:
                payload += addr.to_bytes(16, 'big')
                payload.append(length)
            proc = subprocess.run([helper], input=bytes(payload),
                                  stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            if proc.returncode == 0 and len(proc.stdout) == 129 * 129 * 8:
                vals = struct.unpack('<%dQ' % (129 * 129), proc.stdout)
                return [list(vals[i * 129:(i + 1) * 129]) for i in range(129)]
        except Exception:
            pass
    return compute_f_py(entries, max_stride)


# --------------------------------------------------------------------------
# cut selection
# --------------------------------------------------------------------------

def choose_cuts(table, capacities, max_stride):
    """Minimise the peak utilisation exactly; returns (cuts, used, num, den).

    `cuts` is None when no feasible placement exists.
    """
    stages = len(capacities)
    common = 1
    for cap in capacities:
        common = common // gcd(common, cap) * cap
    best = [dict() for _ in range(stages + 1)]
    parent = [dict() for _ in range(stages + 1)]
    best[0][0] = 0
    for i in range(1, stages + 1):
        factor = common // capacities[i - 1]
        prev = best[i - 1]
        cur = {}
        par = {}
        for end in range(1, 129):
            low = end - max_stride
            if low < 0:
                low = 0
            chosen = None
            chosen_from = None
            for start in range(low, end):
                prior = prev.get(start)
                if prior is None:
                    continue
                value = table[start][end] * factor
                cand = prior if prior > value else value
                if chosen is None or cand < chosen:
                    chosen = cand
                    chosen_from = start
            if chosen is not None:
                cur[end] = chosen
                par[end] = chosen_from
        best[i] = cur
        parent[i] = par
    peak = best[stages].get(128)
    if peak is None or peak > common:
        return None, None, 0, 1
    cuts = [0] * (stages + 1)
    cuts[stages] = 128
    for i in range(stages, 0, -1):
        cuts[i - 1] = parent[i][cuts[i]]
    used = [table[cuts[i]][cuts[i + 1]] for i in range(stages)]
    g = gcd(peak, common)
    return cuts, used, peak // g, common // g


# --------------------------------------------------------------------------
# layout construction
# --------------------------------------------------------------------------

def build_stages(entries, cuts):
    """Deterministic node/rule/edge layout for a cut vector."""
    stages = len(cuts) - 1
    node_lists = []
    for i in range(stages):
        b = cuts[i]
        if i == 0:
            node_lists.append([0])
        else:
            seen = set()
            for addr, length, hop in entries:
                if length > b:
                    seen.add(trunc(addr, b))
            node_lists.append(sorted(seen))
    index_maps = [{a: j for j, a in enumerate(lst)} for lst in node_lists]
    out = []
    for i in range(stages):
        b = cuts[i]
        e = cuts[i + 1]
        grouped = {}
        for item in entries:
            addr, length, hop = item
            if i == 0:
                grouped.setdefault(0, []).append(item)
            elif length > b:
                grouped.setdefault(trunc(addr, b), []).append(item)
        nodes = []
        for node_addr in node_lists[i]:
            rules = []
            edge_prefixes = set()
            for addr, length, hop in grouped.get(node_addr, ()):
                if i == 0:
                    if length == 0 or length <= e:
                        rules.append((length, addr, hop))
                elif length <= e:
                    rules.append((length, addr, hop))
                if length > e:
                    edge_prefixes.add(trunc(addr, e))
            rules.sort(key=lambda t: (t[0], t[1]))
            rule_objs = [{'prefix': canonical_prefix(a, l), 'hop': h}
                         for (l, a, h) in rules]
            edge_objs = []
            if e < 128:
                nxt = index_maps[i + 1]
                for ea in sorted(edge_prefixes):
                    edge_objs.append({'prefix': canonical_prefix(ea, e), 'child': nxt[ea]})
            nodes.append({'prefix': canonical_prefix(node_addr, b),
                          'rules': rule_objs, 'edges': edge_objs})
        out.append({'nodes': nodes})
    return out


# --------------------------------------------------------------------------
# request handling
# --------------------------------------------------------------------------

def _no_duplicate_keys(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise Invalid()
        obj[key] = value
    return obj


def _reject_constant(_text):
    raise Invalid()


def _check_float(value):
    if value != value or value in (float('inf'), float('-inf')):
        raise Invalid()
    return value


def parse_request(line):
    if not isinstance(line, (bytes, bytearray)):
        raise Invalid()
    stripped = line.strip()
    if not stripped.startswith(b'{'):
        raise Invalid()
    try:
        obj = json.loads(stripped, object_pairs_hook=_no_duplicate_keys,
                         parse_constant=_reject_constant, parse_float=_check_float)
    except Invalid:
        raise
    except RecursionError:
        raise Invalid()
    except MemoryError:
        raise Invalid()
    except Exception:
        raise Invalid()
    if not isinstance(obj, dict):
        raise Invalid()
    return obj


def parse_fib(raw):
    if not isinstance(raw, list) or len(raw) > MAX_FIB:
        raise Invalid()
    entries = []
    seen = set()
    for rec in raw:
        if not isinstance(rec, dict) or set(rec.keys()) != {'prefix', 'hop'}:
            raise Invalid()
        text = rec['prefix']
        hop = rec['hop']
        if not isinstance(text, str):
            raise Invalid()
        if not is_int(hop) or hop < 0 or hop > MAX_HOP:
            raise Invalid()
        addr, length = parse_prefix(text)
        key = (addr, length)
        if key in seen:
            raise Invalid()
        seen.add(key)
        entries.append((addr, length, hop))
    return entries


def parse_capacities(raw):
    if not isinstance(raw, list) or not (MIN_STAGES <= len(raw) <= MAX_STAGES):
        raise Invalid()
    for cap in raw:
        if not is_int(cap) or cap < 1 or cap > MAX_CAP:
            raise Invalid()
    return list(raw)


def parse_max_stride(raw):
    if not is_int(raw) or raw < 1 or raw > MAX_STRIDE:
        raise Invalid()
    return raw


def do_compile(req):
    if set(req.keys()) != {'op', 'fib', 'capacities', 'max_stride'}:
        raise Invalid()
    entries = parse_fib(req['fib'])
    capacities = parse_capacities(req['capacities'])
    max_stride = parse_max_stride(req['max_stride'])
    table = compute_f([(a, l) for (a, l, h) in entries], max_stride)
    cuts, used, num, den = choose_cuts(table, capacities, max_stride)
    if cuts is None:
        return {'status': 'infeasible'}
    stages = build_stages(entries, cuts)
    return {
        'status': 'ok',
        'capacities': capacities,
        'max_stride': max_stride,
        'cuts': cuts,
        'stages': stages,
        'used_bits': used,
        'peak': {'num': num, 'den': den},
    }


def validate_image(image):
    """Validate a lookup image; returns (fib entries, capacities, cuts)."""
    if not isinstance(image, dict):
        raise Invalid()
    if set(image.keys()) != {'status', 'capacities', 'max_stride', 'cuts',
                             'stages', 'used_bits', 'peak'}:
        raise Invalid()
    if image['status'] != 'ok':
        raise Invalid()
    capacities = parse_capacities(image['capacities'])
    max_stride = parse_max_stride(image['max_stride'])
    stages = len(capacities)
    cuts = image['cuts']
    if not isinstance(cuts, list) or len(cuts) != stages + 1:
        raise Invalid()
    for c in cuts:
        if not is_int(c) or c < 0 or c > 128:
            raise Invalid()
    if cuts[0] != 0 or cuts[stages] != 128:
        raise Invalid()
    for i in range(stages):
        if cuts[i + 1] <= cuts[i] or cuts[i + 1] - cuts[i] > max_stride:
            raise Invalid()
    stage_objs = image['stages']
    if not isinstance(stage_objs, list) or len(stage_objs) != stages:
        raise Invalid()
    fib = []
    seen = set()
    for i, stage in enumerate(stage_objs):
        if not isinstance(stage, dict) or set(stage.keys()) != {'nodes'}:
            raise Invalid()
        nodes = stage['nodes']
        if not isinstance(nodes, list):
            raise Invalid()
        if i == 0 and len(nodes) != 1:
            raise Invalid()
        b = cuts[i]
        e = cuts[i + 1]
        for node in nodes:
            if not isinstance(node, dict) or set(node.keys()) != {'prefix', 'rules', 'edges'}:
                raise Invalid()
            text = node['prefix']
            if not isinstance(text, str):
                raise Invalid()
            addr, length = parse_prefix(text)
            if length != b or text != canonical_prefix(addr, length):
                raise Invalid()
            rules = node['rules']
            if not isinstance(rules, list):
                raise Invalid()
            for rule in rules:
                if not isinstance(rule, dict) or set(rule.keys()) != {'prefix', 'hop'}:
                    raise Invalid()
                rtext = rule['prefix']
                hop = rule['hop']
                if not isinstance(rtext, str):
                    raise Invalid()
                if not is_int(hop) or hop < 0 or hop > MAX_HOP:
                    raise Invalid()
                raddr, rlen = parse_prefix(rtext)
                if rtext != canonical_prefix(raddr, rlen):
                    raise Invalid()
                key = (raddr, rlen)
                if key in seen:
                    raise Invalid()
                seen.add(key)
                fib.append((raddr, rlen, hop))
            edges = node['edges']
            if not isinstance(edges, list):
                raise Invalid()
            for edge in edges:
                if not isinstance(edge, dict) or set(edge.keys()) != {'prefix', 'child'}:
                    raise Invalid()
                etext = edge['prefix']
                child = edge['child']
                if not isinstance(etext, str):
                    raise Invalid()
                if not is_int(child) or child < 0:
                    raise Invalid()
                eaddr, elen = parse_prefix(etext)
                if elen != e or etext != canonical_prefix(eaddr, elen):
                    raise Invalid()
                if i + 1 < stages:
                    if child >= len(stage_objs[i + 1]['nodes']):
                        raise Invalid()
                elif child != 0:
                    raise Invalid()
    if len(fib) > MAX_FIB:
        raise Invalid()
    # the local rules must reproduce exactly the deterministic layout
    table = compute_f([(a, l) for (a, l, h) in fib], max_stride)
    expected = build_stages(fib, cuts)
    for exp_stage, got_stage in zip(expected, stage_objs):
        exp_nodes = exp_stage['nodes']
        got_nodes = got_stage['nodes']
        if len(exp_nodes) != len(got_nodes):
            raise Invalid()
        for exp_node, got_node in zip(exp_nodes, got_nodes):
            if exp_node['prefix'] != got_node['prefix']:
                raise Invalid()
            if len(exp_node['rules']) != len(got_node['rules']):
                raise Invalid()
            for exp_rule, got_rule in zip(exp_node['rules'], got_node['rules']):
                if exp_rule['prefix'] != got_rule['prefix'] or exp_rule['hop'] != got_rule['hop']:
                    raise Invalid()
            if len(exp_node['edges']) != len(got_node['edges']):
                raise Invalid()
            for exp_edge, got_edge in zip(exp_node['edges'], got_node['edges']):
                if exp_edge['prefix'] != got_edge['prefix'] or exp_edge['child'] != got_edge['child']:
                    raise Invalid()
    used = [table[cuts[i]][cuts[i + 1]] for i in range(stages)]
    for i in range(stages):
        if used[i] > capacities[i]:
            raise Invalid()
    given_used = image['used_bits']
    if not isinstance(given_used, list) or len(given_used) != stages:
        raise Invalid()
    for u in given_used:
        if not is_int(u) or u < 0:
            raise Invalid()
    if list(given_used) != used:
        raise Invalid()
    peak = image['peak']
    if not isinstance(peak, dict) or set(peak.keys()) != {'num', 'den'}:
        raise Invalid()
    num = peak['num']
    den = peak['den']
    if not is_int(num) or not is_int(den) or den <= 0 or num < 0:
        raise Invalid()
    if gcd(num, den) != 1:
        raise Invalid()
    best_num = 0
    best_den = 1
    for i in range(stages):
        g = gcd(used[i], capacities[i])
        p = used[i] // g
        q = capacities[i] // g
        if p * best_den > best_num * q:
            best_num = p
            best_den = q
    if num != best_num or den != best_den:
        raise Invalid()
    return fib, capacities, cuts


def do_lookup(req):
    if set(req.keys()) != {'op', 'image', 'addresses'}:
        raise Invalid()
    raw_addresses = req['addresses']
    if not isinstance(raw_addresses, list) or len(raw_addresses) > MAX_ADDRS:
        raise Invalid()
    fib, capacities, cuts = validate_image(req['image'])
    addrs = []
    for text in raw_addresses:
        if not isinstance(text, str):
            raise Invalid()
        addrs.append(parse_ipv6(text))
    by_length = {}
    for addr, length, hop in fib:
        table = by_length.get(length)
        if table is None:
            table = {}
            by_length[length] = table
        table[trunc(addr, length)] = hop
    lengths = sorted(by_length.keys(), reverse=True)
    masks = [(length, ((1 << length) - 1) << (128 - length), by_length[length])
             for length in lengths]
    cache = {}
    answers = []
    for addr in addrs:
        hit = cache.get(addr)
        if hit is None:
            hop = None
            plen = None
            for length, mask, table in masks:
                found = table.get(addr & mask)
                if found is not None:
                    hop = found
                    plen = length
                    break
            hit = (hop, plen)
            cache[addr] = hit
        answers.append({'hop': hit[0], 'prefix_length': hit[1]})
    return {'status': 'ok', 'answers': answers}


def handle(line):
    req = parse_request(line)
    op = req.get('op')
    if op == 'compile':
        return do_compile(req)
    if op == 'lookup':
        return do_lookup(req)
    raise Invalid()


def main():
    debug = bool(os.environ.get('IPV6_PIPELINE_DEBUG'))
    out = sys.stdout
    for raw in sys.stdin.buffer:
        try:
            response = handle(raw)
        except Invalid:
            response = {'status': 'invalid'}
        except Exception:
            if debug:
                raise
            response = {'status': 'invalid'}
        out.write(json.dumps(response, separators=(',', ':')))
        out.write('\n')
        out.flush()


if __name__ == '__main__':
    main()
